import test from 'node:test';import assert from 'node:assert/strict';import{make,validate,apply,markdown}from './state.js';import{history,transition,undo,portable,parse}from '../creative-kit/state.js';
const config={make,validate,apply};
test('removing a moment preserves interventions; undo restores sequence and placement',()=>{const w=make();let h=history({version:1,activeId:w.id,workspaces:[w]});h=transition(h,{type:'remove-moment',id:'m1'},config);assert.equal(h.present.workspaces[0].ideas[0].momentId,null);assert.equal(h.present.workspaces[0].ideas[0].stale,true);assert.deepEqual(undo(h).present.workspaces[0],w);});
test('scene edits and moving an intervention require a new fit check without erasing reasoning',()=>{const w=make();const text=w.ideas[0].test;apply(w,{type:'edit',collection:'moments',item:'m1',field:'knows',value:'Only yesterday’s value'});assert.equal(w.ideas[0].stale,true);assert.equal(w.ideas[0].test,text);apply(w,{type:'review',id:'i1'});assert.equal(w.ideas[0].stale,false);apply(w,{type:'move-idea',id:'i1',momentId:'m3'});assert.equal(w.ideas[0].stale,true);});
test('portable scenes retain unknowns, order and unplaced ideas; invalid references are rejected',()=>{const w=make();apply(w,{type:'reorder',id:'m3',before:'m1'});assert.equal(w.moments[0].id,'m3');assert.deepEqual(parse(portable(w,'scenes',validate),'scenes',validate),w);assert.ok(markdown(w).includes('Not placed in the scene'));const bad=structuredClone(w);bad.ideas[0].momentId='missing';assert.throws(()=>validate(bad));});
